import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useShop } from '../context/ShopContext';
import { useAuth } from '../context/AuthContext';
import {
  ShoppingBag,
  Trash2,
  Plus,
  Minus,
  ArrowRight,
  Tag,
  ShieldCheck,
  CheckCircle2,
  Info,
  ArrowLeft,
  X,
} from 'lucide-react';

export const Cart: React.FC = () => {
  const {
    cart,
    cartTotal,
    discountAmount,
    finalTotal,
    formatPrice,
    updateQuantity,
    removeFromCart,
    clearCart,
    promoCode,
    discountPct,
    promoNotice,
    applyPromoCode,
    removePromoCode,
    currency,
  } = useShop();
  const { user } = useAuth();
  const navigate = useNavigate();

  const [promoInput, setPromoInput] = useState('');
  const [promoLoading, setPromoLoading] = useState(false);
  const [promoMessage, setPromoMessage] = useState<{ text: string; isError: boolean } | null>(null);

  const handleApplyPromo = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!promoInput.trim()) return;

    setPromoLoading(true);
    setPromoMessage(null);
    try {
      const result = await applyPromoCode(promoInput.trim());
      if (result.success) {
        setPromoMessage({ text: result.message, isError: false });
        setPromoInput('');
      } else {
        setPromoMessage({ text: result.message, isError: true });
      }
    } finally {
      setPromoLoading(false);
    }
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-20 text-center">
        <div className="w-16 h-16 rounded-2xl bg-slate-100 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-400 flex items-center justify-center mx-auto mb-4">
          <ShoppingBag size={32} />
        </div>
        <h1 className="font-display text-2xl font-bold text-slate-900 dark:text-white mb-2">
          Your Cart is Empty
        </h1>
        <p className="text-sm text-slate-500 dark:text-slate-400 mb-8 max-w-md mx-auto">
          Explore our architectural web systems, quantitative trading engines, and masterclasses to add releases to your workspace.
        </p>
        <Link
          to="/shop"
          className="inline-flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-xs font-semibold shadow-lg shadow-emerald-950/20 transition-all"
        >
          <span>Browse Store Catalog</span>
          <ArrowRight size={14} />
        </Link>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto px-4 py-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8 pb-6 border-b border-slate-200 dark:border-slate-800">
        <div>
          <h1 className="font-display text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white">
            Shopping Cart
          </h1>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-slate-400 mt-1">
            {cart.length} release{cart.length === 1 ? '' : 's'} staged for instant checkout
          </p>
        </div>
        <button
          type="button"
          onClick={() => clearCart()}
          className="self-start sm:self-auto text-xs text-rose-500 hover:text-rose-400 font-semibold inline-flex items-center gap-1.5 transition-colors"
        >
          <Trash2 size={13} />
          <span>Clear All</span>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Cart Item Lines */}
        <div className="lg:col-span-8 space-y-4">
          {cart.map(item => {
            const isSingle = item.type === 'course' || item.type === 'subscription';
            return (
              <div
                key={`${item.id}-${item.variants?.[0]?.id || 'std'}`}
                className="p-5 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800/80 shadow-sm flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4"
              >
                <div className="flex items-center gap-4 min-w-0">
                  {item.image ? (
                    <img
                      src={item.image}
                      alt={item.title}
                      className="w-16 h-16 rounded-xl object-cover bg-slate-100 dark:bg-slate-800 shrink-0 border border-slate-200 dark:border-slate-700/60"
                    />
                  ) : (
                    <div className="w-16 h-16 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center shrink-0 text-slate-400">
                      <ShoppingBag size={20} />
                    </div>
                  )}

                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] uppercase font-mono font-bold tracking-wider px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300">
                        {item.type}
                      </span>
                      {item.variants?.[0]?.name && (
                        <span className="text-[10px] font-mono text-emerald-600 dark:text-emerald-400">
                          {item.variants[0].name}
                        </span>
                      )}
                    </div>
                    <Link
                      to={item.type === 'course' ? `/courses/${item.slug || item.id}` : (item.type === 'bundle' ? `/bundles/${item.slug || item.id}` : `/products/${item.slug || item.id}`)}
                      className="font-display text-sm font-semibold text-slate-900 dark:text-white hover:text-emerald-500 transition-colors truncate block mt-1"
                    >
                      {item.title}
                    </Link>
                    <div className="text-xs text-slate-500 dark:text-slate-400 font-mono mt-0.5">
                      {formatPrice(item.price)} each
                    </div>
                  </div>
                </div>

                <div className="flex items-center justify-between sm:justify-end gap-6 w-full sm:w-auto pt-3 sm:pt-0 border-t sm:border-t-0 border-slate-100 dark:border-slate-800/60">
                  {/* Quantity controls */}
                  <div className="flex items-center gap-1.5 border border-slate-200 dark:border-slate-800 rounded-lg p-1 bg-slate-50 dark:bg-slate-900/60">
                    <button
                      type="button"
                      disabled={isSingle}
                      onClick={() => updateQuantity(item.id, -1)}
                      className="p-1 rounded text-slate-500 hover:text-slate-900 dark:hover:text-white disabled:opacity-30 disabled:cursor-not-allowed"
                      aria-label="Decrease quantity"
                    >
                      <Minus size={12} />
                    </button>
                    <span className="w-7 text-center font-mono text-xs font-semibold text-slate-800 dark:text-slate-200">
                      {item.quantity}
                    </span>
                    <button
                      type="button"
                      disabled={isSingle}
                      onClick={() => updateQuantity(item.id, 1)}
                      className="p-1 rounded text-slate-500 hover:text-slate-900 dark:hover:text-white disabled:opacity-30 disabled:cursor-not-allowed"
                      aria-label="Increase quantity"
                    >
                      <Plus size={12} />
                    </button>
                  </div>

                  <div className="text-right">
                    <div className="font-mono text-sm font-bold text-slate-900 dark:text-white">
                      {formatPrice(item.price * item.quantity)}
                    </div>
                  </div>

                  <button
                    type="button"
                    onClick={() => removeFromCart(item.id)}
                    className="p-1.5 text-slate-400 hover:text-rose-500 transition-colors"
                    aria-label="Remove item"
                  >
                    <Trash2 size={15} />
                  </button>
                </div>
              </div>
            );
          })}

          <div className="p-4 rounded-xl bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 flex items-start gap-3 text-xs text-slate-500 dark:text-slate-400">
            <Info size={16} className="text-emerald-500 shrink-0 mt-0.5" />
            <span>
              Prices are calculated strictly in the authoritative Store currency ({currency}). Final eligibility, stock reservations, and promotion discounts are authoritatively verified at checkout.
            </span>
          </div>
        </div>

        {/* Order Summary & Coupon */}
        <div className="lg:col-span-4 space-y-6">
          <div className="p-6 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm space-y-5">
            <h2 className="font-display text-lg font-bold text-slate-900 dark:text-white pb-3 border-b border-slate-100 dark:border-slate-800">
              Order Summary
            </h2>

            {/* Promo Code Input */}
            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-2">
                Promotion Code
              </label>
              {promoCode ? (
                <div className="flex items-center justify-between p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-600 dark:text-emerald-400">
                  <div className="flex items-center gap-2">
                    <Tag size={14} />
                    <span className="font-mono text-xs font-bold">{promoCode}</span>
                    <span className="text-[11px] opacity-80">({discountPct}% off)</span>
                  </div>
                  <button
                    type="button"
                    onClick={removePromoCode}
                    className="p-1 hover:opacity-100 opacity-70"
                    aria-label="Remove promotion code"
                  >
                    <X size={14} />
                  </button>
                </div>
              ) : (
                <form onSubmit={handleApplyPromo} className="flex gap-2">
                  <input
                    type="text"
                    value={promoInput}
                    onChange={e => setPromoInput(e.target.value.toUpperCase())}
                    placeholder="Enter coupon code"
                    className="flex-1 px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white uppercase font-mono tracking-wider focus:outline-none focus:border-emerald-500"
                  />
                  <button
                    type="submit"
                    disabled={promoLoading || !promoInput.trim()}
                    className="px-4 py-2 rounded-xl bg-slate-900 dark:bg-white text-white dark:text-slate-900 text-xs font-semibold disabled:opacity-50 transition-opacity"
                  >
                    {promoLoading ? 'Checking...' : 'Apply'}
                  </button>
                </form>
              )}

              {promoMessage && (
                <p
                  className={`text-xs mt-2 ${
                    promoMessage.isError ? 'text-rose-500' : 'text-emerald-600 dark:text-emerald-400'
                  }`}
                >
                  {promoMessage.text}
                </p>
              )}
              {promoNotice && (
                <p className="text-[11px] text-slate-400 mt-1 leading-relaxed">
                  {promoNotice}
                </p>
              )}
            </div>

            {/* Calculations */}
            <div className="space-y-2.5 pt-4 border-t border-slate-100 dark:border-slate-800 text-xs">
              <div className="flex justify-between text-slate-600 dark:text-slate-400">
                <span>Subtotal ({cart.length} item{cart.length === 1 ? '' : 's'})</span>
                <span className="font-mono font-medium text-slate-900 dark:text-white">
                  {formatPrice(cartTotal)}
                </span>
              </div>

              {discountAmount > 0 && (
                <div className="flex justify-between text-emerald-600 dark:text-emerald-400">
                  <span>Discount Estimate</span>
                  <span className="font-mono font-semibold">
                    -{formatPrice(discountAmount)}
                  </span>
                </div>
              )}

              <div className="pt-3 border-t border-slate-200 dark:border-slate-800 flex justify-between items-baseline">
                <span className="font-display text-sm font-bold text-slate-900 dark:text-white">
                  Estimated Total
                </span>
                <span className="font-mono text-lg font-bold text-emerald-600 dark:text-emerald-400">
                  {formatPrice(finalTotal)}
                </span>
              </div>
            </div>

            {/* Checkout Action */}
            <button
              type="button"
              onClick={() => navigate('/checkout')}
              className="w-full py-3.5 px-4 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs inline-flex items-center justify-center gap-2 shadow-lg shadow-emerald-950/20 transition-all cursor-pointer"
            >
              <span>Proceed to Checkout</span>
              <ArrowRight size={14} />
            </button>

            <div className="flex items-center justify-center gap-2 text-[11px] text-slate-400 pt-1">
              <ShieldCheck size={13} className="text-emerald-500" />
              <span>Official ZarinPal Gateway Checkout</span>
            </div>
          </div>

          <div className="text-center">
            <Link
              to="/shop"
              className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-slate-800 dark:hover:text-slate-200 transition-colors"
            >
              <ArrowLeft size={13} />
              <span>Continue Shopping</span>
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Cart;
